import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  useMediaQuery,
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import { theme } from '../../../theme';
import { useDeletePatientMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors } from '../../../theme/appColors';
import { useFormik } from 'formik';
import { IUserInfo } from '../../../core/Interface/patient.interface';
interface INewPatient {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: IUserInfo;
}

const DeletePatient = ({
  title,
  openModel = true,
  handleCloseDialog,
  data,
}: INewPatient) => {
  const { t } = useTranslation(['common', 'product', 'category']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [deletePatient, { isLoading }] = useDeletePatientMutation();
  const { showErrorMessage, showMessage } = useNotifier();

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      name: data?.name,
      mobile: data?.mobile,
      address: data?.address,
      dateOfBirth: data?.dateOfBirth || new Date('2023-12-31'),
      email: '',
    },
    onSubmit: async (values) => {
      try {
        const response = await deletePatient(data?.id|| '').unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });
  const formValid = React.useMemo(() => {
    return formik.values.name === '' || formik.values.name === undefined
      ? false
      : true;
  }, [formik]);

  const buttonText = data ? t('common:delete') : t('common:create');

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Box>
              Do you want to delete <strong>{data?.name}</strong>
            </Box>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={() => {
                handleClose();
              }}
              sx={{ width: 200, height: 42, borderRadius: '5px' }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{ width: 200, height: 42, borderRadius: '5px' }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(DeletePatient);