import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useTranslation } from 'react-i18next';
import useUser from '../../../core/hooks/useUser';
import {
  Box,
  Button,
  Card,
  CardActions,
  CardContent,
  Chip,
  IconButton,
  InputAdornment,
  Skeleton,
  TextField,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useVirtualizer } from '@tanstack/react-virtual';
import AnimatedPage from '../../../layouts/AnimatedPage';
import { useGetAllPatientsQuery } from '../../posApi';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import SearchIcon from '@mui/icons-material/Search';
import PeopleAltOutlinedIcon from '@mui/icons-material/PeopleAltOutlined';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import CakeOutlinedIcon from '@mui/icons-material/CakeOutlined';
import dayjs from 'dayjs';
import NewPatient from '../Treatments/components/NewPatient';
import { Privileges } from '../../../core/types/commonType';
import DeletePatient from './DeletePatient';
import { IPatient, IUserInfo } from '../../../core/Interface/patient.interface';

// ─── design tokens ────────────────────────────────────────────────────────────

const TEAL  = '#0F8B8D';
const NAVY  = '#0F1D4D';
const MID   = '#1E3A8A';

const ACCENT_COLORS = [
  '#F97316', '#06B6D4', '#8B5CF6', '#22C55E',
  '#0EA5E9', '#EC4899', '#F59E0B', '#14B8A6',
];

// ─── PatientCard ──────────────────────────────────────────────────────────────

interface IPatientRecord {
  id: string;
  patientNumber: string;
  name: string;
  mobile?: string;
  address?: string;
  dateOfBirth?: string;
  age?: number;
}

interface IPatientCardProps {
  accent: string;
  canDelete: boolean;
  canEdit: boolean;
  patient: IPatientRecord;
  onDelete: (p: IPatientRecord) => void;
  onEdit: (p: IPatientRecord) => void;
}

// eslint-disable-next-line react/no-multi-comp
const PatientCard = React.memo(({
  accent,
  canDelete,
  canEdit,
  patient,
  onDelete,
  onEdit,
}: IPatientCardProps) => {
  const initials = patient.name
    .split(' ')
    .map((w) => w[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

  return (
    <Box sx={{ flex: 1, minWidth: 0 }}>
      <Card
        sx={{
          background: `linear-gradient(145deg,rgba(255,255,255,0.98) 0%,${alpha(accent, 0.06)} 100%)`,
          border: `1px solid ${alpha(accent, 0.22)}`,
          borderRadius: '12px',
          height: '100%',
          overflow: 'hidden',
        }}
        variant="outlined"
      >
        {/* accent bar */}
        <Box
          sx={{
            background: `linear-gradient(90deg, ${accent} 0%, ${alpha(accent, 0.4)} 100%)`,
            height: 3,
          }}
        />

        <CardContent sx={{ pb: '8px !important', pt: 2, px: 2 }}>
          {/* Avatar + name + ID */}
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexDirection: 'column',
              gap: 0.75,
              mb: 1.5,
            }}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: `linear-gradient(135deg, ${accent} 0%, ${alpha(accent, 0.6)} 100%)`,
                borderRadius: '50%',
                color: '#fff',
                display: 'flex',
                fontSize: 18,
                fontWeight: 800,
                height: 52,
                justifyContent: 'center',
                width: 52,
              }}
            >
              {initials}
            </Box>

            <Tooltip
              arrow
              title={patient.name}
            >
              <Typography
                sx={{
                  color: NAVY,
                  fontSize: 14,
                  fontWeight: 700,
                  overflow: 'hidden',
                  textAlign: 'center',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                  width: '100%',
                }}
              >
                {patient.name}
              </Typography>
            </Tooltip>

            <Chip
              label={`ID: ${patient.patientNumber}`}
              size="small"
              sx={{
                background: alpha(accent, 0.1),
                border: `1px solid ${alpha(accent, 0.25)}`,
                color: accent,
                fontSize: 10,
                fontWeight: 700,
                height: 20,
              }}
            />
          </Box>

          {/* Info rows */}
          <Box
            sx={{
              borderTop: `1px solid ${alpha(accent, 0.12)}`,
              display: 'flex',
              flexDirection: 'column',
              gap: 0.75,
              pt: 1.25,
            }}
          >
            <InfoRow
              icon={<PhoneOutlinedIcon sx={{ fontSize: 12, color: TEAL }} />}
              value={patient.mobile || '—'}
            />
            <InfoRow
              icon={<HomeOutlinedIcon sx={{ fontSize: 12, color: TEAL }} />}
              value={
                patient.address && patient.address.length > 22
                  ? `${patient.address.slice(0, 22)}…`
                  : (patient.address || '—')
              }
            />
            <InfoRow
              icon={<CakeOutlinedIcon sx={{ fontSize: 12, color: TEAL }} />}
              value={
                patient.dateOfBirth
                  ? dayjs(patient.dateOfBirth).format('DD MMM YYYY')
                  : '—'
              }
            />
          </Box>
        </CardContent>

        {(canEdit || canDelete) && (
          <CardActions
            sx={{
              borderTop: `1px solid ${alpha(accent, 0.12)}`,
              justifyContent: 'flex-end',
              pb: 1,
              pt: 0.75,
              px: 1.5,
            }}
          >
            {canEdit && (
              <Tooltip title="Edit patient">
                <IconButton
                  onClick={() => onEdit(patient)}
                  size="small"
                  sx={{
                    background: alpha('#22C55E', 0.1),
                    borderRadius: '6px',
                    height: 30,
                    width: 30,
                    '&:hover': { background: alpha('#22C55E', 0.2) },
                  }}
                >
                  <EditIcon sx={{ color: '#22C55E', fontSize: 15 }} />
                </IconButton>
              </Tooltip>
            )}
            {canDelete && (
              <Tooltip title="Delete patient">
                <IconButton
                  onClick={() => onDelete(patient)}
                  size="small"
                  sx={{
                    background: alpha('#DC2626', 0.08),
                    borderRadius: '6px',
                    height: 30,
                    width: 30,
                    '&:hover': { background: alpha('#DC2626', 0.15) },
                  }}
                >
                  <DeleteIcon sx={{ color: '#DC2626', fontSize: 15 }} />
                </IconButton>
              </Tooltip>
            )}
          </CardActions>
        )}
      </Card>
    </Box>
  );
});
PatientCard.displayName = 'PatientCard';

// ─── InfoRow ──────────────────────────────────────────────────────────────────

// eslint-disable-next-line react/no-multi-comp
const InfoRow = ({ icon, value }: { icon: React.ReactNode; value: string }) => (
  <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75 }}>
    <Box sx={{ flexShrink: 0, lineHeight: 0 }}>{icon}</Box>
    <Typography
      sx={{
        color: alpha(NAVY, 0.65),
        fontSize: 12,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      }}
    >
      {value}
    </Typography>
  </Box>
);

// ─── VirtualPatientGrid ───────────────────────────────────────────────────────

interface IVirtualGridProps {
  canDelete: boolean;
  canEdit: boolean;
  patients: IPatientRecord[];
  showSkeleton: boolean;
  onDelete: (p: IPatientRecord) => void;
  onEdit: (p: IPatientRecord) => void;
}

// eslint-disable-next-line react/no-multi-comp
const VirtualPatientGrid = React.memo(({
  canDelete,
  canEdit,
  patients,
  showSkeleton,
  onDelete,
  onEdit,
}: IVirtualGridProps) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [colCount, setColCount] = useState(4);

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth;
      if (w >= 1536) setColCount(6);
      else if (w >= 1200) setColCount(4);
      else if (w >= 900) setColCount(3);
      else if (w >= 600) setColCount(2);
      else setColCount(1);
    };
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [patients]);

  const rows = useMemo(() => {
    const r: IPatientRecord[][] = [];
    for (let i = 0; i < patients.length; i += colCount) {
      r.push(patients.slice(i, i + colCount));
    }
    return r;
  }, [patients, colCount]);

  const virtualizer = useVirtualizer({
    count: rows.length,
    estimateSize: () => 282,
    getScrollElement: () => scrollRef.current,
    overscan: 3,
  });

  const scrollBoxSx = {
    height: 'calc(100vh - 260px)',
    overflowX: 'hidden' as const,
    overflowY: 'auto' as const,
    scrollbarWidth: 'thin' as const,
    '&::-webkit-scrollbar': { width: '4px' },
    '&::-webkit-scrollbar-thumb': {
      backgroundColor: alpha(TEAL, 0.3),
      borderRadius: '4px',
    },
  };

  if (showSkeleton) {
    return (
      <Box sx={scrollBoxSx}>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2 }}>
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <Box
              key={i}
              sx={{ flex: '0 0 calc(25% - 12px)' }}
            >
              <Skeleton
                height={266}
                sx={{ borderRadius: '12px' }}
                variant="rectangular"
              />
            </Box>
          ))}
        </Box>
      </Box>
    );
  }

  if (patients.length === 0) {
    return (
      <Box
        sx={{
          alignItems: 'center',
          background: alpha(NAVY, 0.03),
          border: `1px dashed ${alpha(NAVY, 0.15)}`,
          borderRadius: '12px',
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          py: 8,
        }}
      >
        <PersonOutlineIcon sx={{ color: alpha(NAVY, 0.2), fontSize: 48 }} />
        <Typography sx={{ color: alpha(NAVY, 0.4), fontWeight: 600 }}>
          No patients found
        </Typography>
      </Box>
    );
  }

  return (
    <Box
      ref={scrollRef}
      sx={scrollBoxSx}
    >
      <Box sx={{ height: `${virtualizer.getTotalSize()}px`, position: 'relative' }}>
        {virtualizer.getVirtualItems().map((vi) => {
          const row = rows[vi.index];
          return (
            <Box
              data-index={vi.index}
              key={vi.index}
              ref={virtualizer.measureElement}
              sx={{
                display: 'flex',
                gap: 2,
                left: 0,
                pb: 2,
                position: 'absolute',
                right: 0,
                top: 0,
                transform: `translateY(${vi.start}px)`,
              }}
            >
              {row.map((patient, idx) => (
                <PatientCard
                  // eslint-disable-next-line max-len
                  accent={ACCENT_COLORS[(vi.index * colCount + idx) % ACCENT_COLORS.length]}
                  canDelete={canDelete}
                  canEdit={canEdit}
                  key={patient.id}
                  onDelete={onDelete}
                  onEdit={onEdit}
                  patient={patient}
                />
              ))}
              {Array.from({ length: colCount - row.length }).map((_, i) => (
                <Box
                  key={`pad-${i}`}
                  sx={{ flex: 1 }}
                />
              ))}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
});
VirtualPatientGrid.displayName = 'VirtualPatientGrid';

// ─── Patients ─────────────────────────────────────────────────────────────────

// eslint-disable-next-line react/no-multi-comp
const Patients = () => {
  const { t } = useTranslation(['common']);
  const { userHasRight } = useUser();
  const [searchText, setSearchText] = useState('');
  const [open, setOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [userData, setUserData] = useState<IUserInfo | undefined>(undefined);

  const { data, isLoading } = useGetAllPatientsQuery({
    pageIndex: 0,
    pageSize: 100000,
    searchText,
  });

  const patients = useMemo<IPatientRecord[]>(() => {
    const d = data?.data as IPatient;
    return d?.records ?? [];
  }, [data?.data]);

  const canEdit   = userHasRight(Privileges.PatientAdd);
  const canDelete = userHasRight(Privileges.PatientAdd);

  const handleEdit = useCallback((p: IPatientRecord) => {
    setUserData(p as unknown as IUserInfo);
    setOpen(true);
  }, []);

  const handleDelete = useCallback((p: IPatientRecord) => {
    setUserData(p as unknown as IUserInfo);
    setDeleteOpen(true);
  }, []);

  return (
    <AnimatedPage>
      <Box data-testid="patient-management">

        {/* ── Hero banner ─────────────────────────────────────────── */}
        <Box
          sx={{
            background: `linear-gradient(135deg, ${NAVY} 0%, ${MID} 45%, ${TEAL} 100%)`,
            borderRadius: 2,
            color: '#fff',
            mb: 3,
            overflow: 'hidden',
            position: 'relative',
            px: { xs: 2, md: 3 },
            py: { xs: 1.5, md: 2 },
          }}
        >
          {/* decorative blobs */}
          <Box sx={{ background: 'rgba(255,255,255,0.07)', borderRadius: '50%', height: 220, inset: 'auto -60px -100px auto', pointerEvents: 'none', position: 'absolute', width: 220 }} />
          <Box sx={{ background: 'rgba(255,255,255,0.05)', borderRadius: '50%', height: 260, inset: '-100px auto auto 55%', pointerEvents: 'none', position: 'absolute', width: 260 }} />

          <Box
            sx={{
              alignItems: { xs: 'flex-start', sm: 'center' },
              display: 'flex',
              flexDirection: { xs: 'column', sm: 'row' },
              gap: 2,
              justifyContent: 'space-between',
              position: 'relative',
            }}
          >
            {/* title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  backdropFilter: 'blur(8px)',
                  background: 'rgba(255,255,255,0.14)',
                  border: '1px solid rgba(255,255,255,0.18)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 44,
                  justifyContent: 'center',
                  width: 44,
                }}
              >
                <PeopleAltOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography
                  sx={{
                    color: '#fff',
                    fontSize: { xs: '1rem', md: '1.2rem' },
                    fontWeight: 800,
                    letterSpacing: '-0.02em',
                    lineHeight: 1.2,
                  }}
                >
                  Patient Management
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}>
                  {isLoading ? '—' : `${patients.length} patients registered`}
                </Typography>
              </Box>
            </Box>

            {/* search + add */}
            <Box
              sx={{
                alignItems: 'center',
                display: 'flex',
                flexWrap: 'wrap',
                gap: 1.5,
                position: 'relative',
              }}
            >
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: alpha('#fff', 0.6), fontSize: 18 }} />
                    </InputAdornment>
                  ),
                  sx: {
                    color: '#fff',
                    '& .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.35)' },
                    '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.6)' },
                    '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: '#fff' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.5)' },
                  },
                }}
                autoComplete="off"
                onChange={(e) => setSearchText(e.target.value)}
                placeholder="Search by name or mobile…"
                size="small"
                sx={{ width: 260 }}
                value={searchText}
                variant="outlined"
              />

              {userHasRight(Privileges.PatientAdd) && (
                <Button
                  onClick={() => { setUserData(undefined); setOpen(true); }}
                  startIcon={<AddIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                    borderRadius: '8px',
                    boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                    color: '#fff',
                    fontWeight: 700,
                    height: 40,
                    px: 2.5,
                    '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                  }}
                  variant="contained"
                >
                  {t('common:create')} Patient
                </Button>
              )}
            </Box>
          </Box>
        </Box>

        {/* ── Virtual patient grid ──────────────────────────────────── */}
        <VirtualPatientGrid
          canDelete={canDelete}
          canEdit={canEdit}
          onDelete={handleDelete}
          onEdit={handleEdit}
          patients={patients}
          showSkeleton={isLoading}
        />
      </Box>

      {open && (
        <NewPatient
          data={userData}
          handleCloseDialog={() => setOpen(false)}
          openModel={open}
          title={userData ? 'Edit Patient' : 'Create New Patient'}
        />
      )}

      {deleteOpen && (
        <DeletePatient
          data={userData}
          handleCloseDialog={() => setDeleteOpen(false)}
          openModel={deleteOpen}
          title="Delete Patient"
        />
      )}
    </AnimatedPage>
  );
};

export default Patients;
